mapper.select:
SELECT a.system_code , a.module_code , a.code_type_code , a.code_type_code_desc , a.control_level_code , a.access_level_code , a.use_flag FROM lgcom_code_type_code_c a WHERE 1=1 AND UPPER(a.code_type_code) like UPPER(#{codeType}) || '%'
AND a.system_code = #{systemCode}
AND a.module_code = #{moduleCode}
AND a.use_flag = #{useFlag}
ORDER BY a.system_code, a.module_code, a.code_type_code


SELECT 	COUNT(a.code_type_code) AS cnt
FROM 	lgcom_code_type_code_c a
WHERE   a.code_type_code = #{codeTypeCode}


SELECT 	COUNT(a.code_type_code) AS cnt
FROM 	lgcom_code_type_code_access_n a
WHERE   a.code_type_code = #{codeTypeCode}	
AND		a.role_code = #{roleCode}

mapper.insert:
		INSERT INTO LGCOM_CODE_TYPE_CODE_C
		(  CODE_TYPE_CODE
 		 , SYSTEM_CODE
 		 , MODULE_CODE
 		 , CODE_TYPE_CODE_DESC
 		 , CONTROL_LEVEL_CODE
 		 , ACCESS_LEVEL_CODE
 		 , USE_FLAG
 		 , CREATED_BY
 		 , CREATION_DATE
 		 , LAST_UPDATED_BY
 		 , LAST_UPDATE_DATE
		) values
		(  #{codeTypeCode}
		 , #{systemCode}
		 , #{moduleCode}
		 , #{codeTypeCodeDesc}
		 , #{controlLevelCode}
		 , #{accessLevelCode}
		 , #{useFlag}
		 , #{sessionUserId}
		 , SYSDATE
		 , #{sessionUserId}
		 , SYSDATE
		)

mapper.update:
UPDATE LGCOM_CODE_TYPE_CODE_C
   SET SYSTEM_CODE      	= #{systemCode}
     , MODULE_CODE   		= #{moduleCode}
     , CODE_TYPE_CODE_DESC 	= #{codeTypeCodeDesc}
     , CONTROL_LEVEL_CODE 	= #{controlLevelCode}
     , ACCESS_LEVEL_CODE 	= #{accessLevelCode}
     , USE_FLAG 			= #{useFlag}		   
     , LAST_UPDATED_BY    	= #{sessionUserId}
     , LAST_UPDATE_DATE    	= SYSDATE
 WHERE CODE_TYPE_CODE 	= #{codeTypeCode}

UPDATE LGCOM_CODE_TYPE_CODE_ACCESS_N
   SET UPDATE_ENABLE_FLAG	= #{updateEnableFlag}
     , LAST_UPDATED_BY    	= #{sessionUserId}
     , LAST_UPDATE_DATE    	= SYSDATE
 WHERE CODE_TYPE_CODE 		= #{codeTypeCode}
   AND ROLE_CODE 			= #{roleCode}

DELETE LGCOM_CODE_TYPE_CODE_ACCESS_N
 WHERE CODE_TYPE_CODE = #{codeTypeCode}
   AND ROLE_CODE 	  = #{roleCode}
